property.value:
let $words := function($segment) {
  tokenize(lower-case(replace(replace(replace(string($segment), '\[\d+\]', ''),
    '([a-z\d])([A-Z])', '$1-$2'), '([A-Z])([A-Z][a-z])', '$1-$2')), '[-_]+')[. != '']
},
    $secret := function($key) {
  let $segments := tokenize(string($key), '\.'),
      $last := $words($segments[last()]),
      $owner := $words($segments[last() - 1])[last()],
      $names := ('password', 'passwd', 'passphrase', 'secret', 'token', 'credential', 'credentials', 'apikey', 'privatekey',
        'secretkey', 'accesskey', 'signingkey', 'encryptionkey', 'hmackey', 'jwtkey', 'cryptokey', 'masterkey')
  return $last[last()] = $names
    or (count($last) > 1 and string-join(subsequence($last, count($last) - 1), '') = $names)
    or (count($last) = 1 and $last = 'key'
      and $owner = ('api', 'jwt', 'encryption', 'signing', 'hmac', 'crypto', 'master', 'access', 'secret', 'private'))
},
    $fallback := function($value) {
  string-length($value) > 0 and not(matches($value, '^[#$]'))
}
return
//Annotation[pmd-java:typeIs('org.springframework.beans.factory.annotation.Value')]
  //StringLiteral[matches(@ConstValue, '^\$\{[^}:]+:[^}]*\}$')]
  [$secret(substring-before(substring-after(@ConstValue, '${'), ':'))]
  [$fallback(replace(@ConstValue, '^\$\{[^}:]+:(.*)\}$', '$1'))]
|
//Annotation[pmd-java:typeIs('org.springframework.boot.context.properties.bind.DefaultValue')]
  [$secret(../../VariableId/@Name)]
  [.//StringLiteral[$fallback(@ConstValue)]]
|
//ClassDeclaration/ModifierList/Annotation[pmd-java:typeIs('org.springframework.boot.context.properties.ConfigurationProperties')]
  /../../ClassBody/FieldDeclaration[not(pmd-java:modifiers() = 'static')]
  [let $prefix := ../../ModifierList/Annotation[pmd-java:typeIs('org.springframework.boot.context.properties.ConfigurationProperties')]
      /AnnotationMemberList/MemberValuePair[@Name = ('value', 'prefix')]/StringLiteral/@ConstValue
   return $secret(string-join(($prefix, VariableDeclarator/VariableId/@Name), '.'))]
  [VariableDeclarator/StringLiteral[$fallback(@ConstValue)]]
|
//MethodCall[@MethodName = 'getProperty'][*[1][pmd-java:typeIs('org.springframework.core.env.PropertyResolver')]]
  [ArgumentList[count(*) = 2]/*[1][self::StringLiteral][$secret(@ConstValue)]]
  [ArgumentList/*[2][self::StringLiteral][$fallback(@ConstValue)]]
